package com.lianxibu.site.service.articles;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.articles.JdbcArticleEntityReads;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import java.time.Instant;
import java.sql.Timestamp;
import java.util.List;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
class ArticleEntityProjectionServiceTest {
 private JdbcTemplate jdbc;private ArticlesService base;private ArticleEntityProjectionService service;private final Actor user=new Actor("fictional-user","user");
 private final ArticlesService.Article article=new ArticlesService.Article("fictional-article","Fictional article",null,"fictional-source","Fictional source","https://example.invalid/story",null,Instant.parse("2026-01-09T00:00:00Z"),null,null,"unavailable",1,null);
 @BeforeEach void setup(){var ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:fictional-article-entity-"+System.nanoTime()+";DB_CLOSE_DELAY=-1");jdbc=new JdbcTemplate(ds);jdbc.execute("CREATE TABLE source_run_items(id VARCHAR(64) PRIMARY KEY,article_id VARCHAR(64),source_id VARCHAR(80),category VARCHAR(32),entity_id VARCHAR(64),terminal_state VARCHAR(32),effective_valid INT,state VARCHAR(32))");jdbc.execute("CREATE TABLE analyzed_entities(id VARCHAR(64) PRIMARY KEY,category VARCHAR(32),first_recorded_at TIMESTAMP,first_seen_business_date DATE,last_seen_at TIMESTAMP,occurrence_count BIGINT,repeat_count BIGINT,analysis_state VARCHAR(32),revision BIGINT,raw_json CLOB)");jdbc.update("INSERT INTO analyzed_entities VALUES('fictional-entity','news_tech',?,NULL,?,3,2,'analyzed',4,'Fictional private payload')",Timestamp.from(Instant.parse("2026-01-01T00:00:00Z")),Timestamp.from(Instant.parse("2026-01-03T00:00:00Z")));base=mock(ArticlesService.class);when(base.article(user,"fictional-article")).thenReturn(article);when(base.listArticles(user,null,null,null,1,20)).thenReturn(new ArticlesService.ArticlePage(List.of(article),1,20,1));service=new ArticleEntityProjectionService(base,new JdbcArticleEntityReads(ds),new DataSourceTransactionManager(ds));link("fictional-item","fictional-entity","news_tech","fictional-source","ready");}
 @Test void uniqueSameEntityObservationsUseDirectMetadataAndDoNotExposeRawBody(){link("fictional-repeat","fictional-entity","news_tech","fictional-source","analyzed");var row=service.articleWithEntity(user,"fictional-article");assertEquals("fictional-entity",row.entitySummary().id());assertEquals(Instant.parse("2026-01-01T00:00:00Z"),row.entitySummary().firstRecordedAt());assertNotEquals(article.observedAt(),row.entitySummary().firstRecordedAt());assertEquals(3L,row.entitySummary().occurrenceCount());assertEquals(2L,row.entitySummary().repeatCount());assertEquals("analyzed",row.entitySummary().analysisState());assertFalse(row.entitySummary().toString().contains("payload"));assertSame(article,row.article());assertEquals(1,service.listArticlesWithEntity(user,null,null,null,1,20).total());}
 @Test void absentAmbiguousWrongKindSourceOrUnresolvedAssociationsAreNull(){jdbc.execute("DELETE FROM source_run_items");assertNull(service.articleWithEntity(user,"fictional-article").entitySummary());for(String field:List.of("entity_id","category","source_id","state")){jdbc.execute("DELETE FROM source_run_items");link("fictional-item","fictional-entity","news_tech","fictional-source","ready");jdbc.update("UPDATE source_run_items SET "+field+"=? WHERE id=?",field.equals("entity_id")?null:field.equals("category")?"model":field.equals("source_id")?"fictional-other-source":"needs_review","fictional-item");assertNull(service.articleWithEntity(user,"fictional-article").entitySummary());}jdbc.execute("DELETE FROM source_run_items");link("fictional-item","fictional-entity","news_tech","fictional-source","ready");link("fictional-other","fictional-other-entity","news_tech","fictional-source","ready");assertNull(service.articleWithEntity(user,"fictional-article").entitySummary());jdbc.update("DELETE FROM source_run_items WHERE id=?","fictional-other");jdbc.update("UPDATE analyzed_entities SET category='model'");assertNull(service.articleWithEntity(user,"fictional-article").entitySummary());}
 @Test void excludedInvalidOrPendingRowsDoNotContributeAndDanglingEntityIsUnknown(){link("fictional-excluded","fictional-other","model","fictional-source","excluded");link("fictional-invalid","fictional-other","news_tech","fictional-source","ready");jdbc.update("UPDATE source_run_items SET effective_valid=0 WHERE id='fictional-invalid'");link("fictional-pending","fictional-other","news_tech","fictional-source","ready");jdbc.update("UPDATE source_run_items SET terminal_state='pending' WHERE id='fictional-pending'");assertNotNull(service.articleWithEntity(user,"fictional-article").entitySummary());jdbc.execute("DELETE FROM analyzed_entities");assertNull(service.articleWithEntity(user,"fictional-article").entitySummary());}
 @Test void unknownCountsTimesAndStateStayUnknownButImpossibleCountsAndTimesFailClosed(){jdbc.update("UPDATE analyzed_entities SET occurrence_count=NULL,repeat_count=NULL,first_recorded_at=NULL,last_seen_at=NULL,analysis_state='legacy_unknown'");var summary=service.articleWithEntity(user,"fictional-article").entitySummary();assertNull(summary.occurrenceCount());assertNull(summary.repeatCount());assertNull(summary.firstRecordedAt());assertNull(summary.analysisState());jdbc.update("UPDATE analyzed_entities SET occurrence_count=3,repeat_count=0");assertThrows(IllegalStateException.class,()->service.articleWithEntity(user,"fictional-article"));jdbc.update("UPDATE analyzed_entities SET occurrence_count=NULL,repeat_count=0");assertThrows(IllegalStateException.class,()->service.articleWithEntity(user,"fictional-article"));jdbc.update("UPDATE analyzed_entities SET occurrence_count=0,repeat_count=0,first_recorded_at=?,last_seen_at=?",Timestamp.from(Instant.parse("2026-01-03T00:00:00Z")),Timestamp.from(Instant.parse("2026-01-01T00:00:00Z")));assertThrows(IllegalStateException.class,()->service.articleWithEntity(user,"fictional-article"));}
 @Test void allPagesOfAssociationEvidenceAreReadAndLateAmbiguityIsNotHidden(){for(int i=0;i<500;i++)link(String.format("fictional-repeat-%04d",i),"fictional-entity","news_tech","fictional-source","ready");link("fictional-z-ambiguous","fictional-other-entity","news_tech","fictional-source","ready");assertNull(service.articleWithEntity(user,"fictional-article").entitySummary());}
 @Test void deniedActorsNeverReadAndOldReadsRemainUnchanged(){assertSame(article,service.article(user,"fictional-article"));reset(base);jdbc.execute("DROP TABLE source_run_items");assertThrows(ArticleEntityProjectionService.Denied.class,()->service.articleWithEntity(null,"fictional-article"));verifyNoInteractions(base);}
 private void link(String id,String entity,String kind,String source,String state){jdbc.update("INSERT INTO source_run_items VALUES(?,?,?,?,?,'accepted',1,?)",id,"fictional-article",source,kind,entity,state);}
}
